use crate::models::EngineManifest;
use serde::Deserialize;
use std::collections::HashMap;

const RAW_ENGINES_JSON: &str = include_str!("../../../shared/data/engines.json");

#[derive(Deserialize)]
struct EnginesFile {
    engines: Vec<EngineManifest>,
}

pub struct EngineRegistry {
    engines: HashMap<String, EngineManifest>,
}

impl EngineRegistry {
    /// Loads the manifests generated by `scripts/build-engines.mjs`
    /// (`shared/data/engines.json`). The frontend imports the same file.
    ///
    /// The file is embedded at compile time; a parse failure means the
    /// generated data is out of sync and is reported to `main` instead of
    /// panicking.
    pub fn new() -> Result<Self, String> {
        let parsed: EnginesFile = serde_json::from_str(RAW_ENGINES_JSON)
            .map_err(|e| format!("shared/data/engines.json is invalid: {e}"))?;
        let engines = parsed.engines.into_iter().map(|e| (e.id.clone(), e)).collect();
        Ok(Self { engines })
    }

    pub fn get(&self, id: &str) -> Option<&EngineManifest> {
        self.engines.get(id)
    }

    pub fn list(&self) -> Vec<EngineManifest> {
        let mut list: Vec<EngineManifest> = self.engines.values().cloned().collect();
        list.sort_by(|a, b| a.id.cmp(&b.id));
        list
    }
}

